/* Independently implemented row actions; messages require an explicit user click. */
function whatsappNumber(value){let n=String(value||'').replace(/\D/g,'');if(n.length===10)n='91'+n;return n.length>=11&&n.length<=15?n:''}
function extraButton(action,key,id,title,color,symbol){return `<button type="button" class="btn small extraAction ${color}" data-extra-action="${action}" data-key="${key}" data-id="${esc(id)}" title="${title}" aria-label="${title}">${['whatsapp','reminder'].includes(action)?whatsappIcon():({details:'eye','copy-policy':'copy',thermal:'receipt',archive:'trash',salary:'rupee','staff-jobs':'clipboard',undo:'undo'}[action]?icon({details:'eye','copy-policy':'copy',thermal:'receipt',archive:'trash',salary:'rupee','staff-jobs':'clipboard',undo:'undo'}[action]):symbol)}</button>`}
function policyContact(r){let bike=find('bikes',r.bike),c=bike&&find('customers',bike.customer);return {name:r.customerName||c?.name||'',mobile:r.mobile||c?.mobile||'',vehicle:r.vehicleNumber||bike?.number||''}}
function policyMessage(r){let c=policyContact(r);return `${db.settings.name}\nInsurance Policy Details\nCustomer: ${c.name}\nVehicle: ${c.vehicle}\nInsurance Company: ${r.provider||''}\nPolicy: ${r.policy||''}\nIssue: ${r.issue||''}\nExpiry: ${r.expiry||''}\nPremium: ${money(r.premium||0)}`}
function messagePreview(phone,message){let n=whatsappNumber(phone);openModal('WhatsApp — Review Message',`<div class="formbody"><p>${n?'Review the message, then open WhatsApp to choose whether to send.':'A valid mobile number is needed. Update the customer or policy contact first.'}</p><textarea id="whatsappMessage" aria-label="WhatsApp message" rows="12" style="width:100%">${esc(message)}</textarea><p>A WhatsApp web link cannot attach local files. When a file sharing option is shown below, use it to share the message and files together; otherwise attach files in WhatsApp manually.</p></div><div class="formactions">${btn('Close','cancel','secondary')}${n?'<a class="btn success" id="openWhatsapp" target="_blank" rel="noopener noreferrer">Open WhatsApp</a>':''}</div>`);if(n){let link=$('#openWhatsapp'),sync=()=>link.href='https://wa.me/'+n+'?text='+encodeURIComponent($('#whatsappMessage').value);sync();$('#whatsappMessage').oninput=sync}}
function showPolicy(r){openModal('Insurance — Full Details',`<div class="formbody"><pre style="white-space:pre-wrap;font:inherit">${esc(policyMessage(r))}</pre><p>Mobile: ${esc(policyContact(r).mobile||'Not supplied')}</p><p>Email: ${esc(r.email||'—')}</p><p>Address: ${esc(r.address||'—')}</p><p>Notes: ${esc(r.notes||'—')}</p><p>Policy files can be selected from this device temporarily when sharing; they are not saved with the policy.</p><p>Online tracking requires a hosted customer portal. This local version has no public tracking link.</p></div><div class="formactions">${btn('Close','cancel','secondary')}${extraButton('copy-policy','insurance',r.id,'Copy policy details','blue','Copy Details')}</div>`)}
function archiveBill(key,id){let b=find(key,id);if(!b||!window.confirm('Move '+id+' to the recycle bin? Linked receipts will move with it. Stock and balances will be recalculated.'))return;let snapshot=JSON.parse(JSON.stringify(db)),receipts=db.receipts.filter(r=>r.bill===id);db.trash=db.trash||[];db.trash.push({key,record:b,receipts,removedAt:new Date().toISOString()});db[key]=db[key].filter(r=>r.id!==id);db.receipts=db.receipts.filter(r=>r.bill!==id);audit('Archive',id+' moved to recycle bin');if(save('Moved to recycle bin')===false){db=snapshot;return}render();openModal('Moved to Recycle Bin',`<div class="formbody"><p>${esc(id)} and its linked receipts were moved to the recycle bin.</p></div><div class="formactions">${btn('Close','cancel','secondary')}${extraButton('undo',key,id,'Restore record','blue','Undo')}</div>`)}
const basicBeforeActions=basicPage;
basicPage=function(key){if(key!=='insurance')return basicBeforeActions(key);return toolbar('Add Insurance Policy')+table(['Vehicle Number','Customer Name','Mobile Number','Insurance Company / Policy','Issue Date','Expiry Date','Premium','PDF','Actions'],db.insurance.filter(matches).map(r=>{let c=policyContact(r),n=whatsappNumber(c.mobile);return [esc(c.vehicle),esc(c.name),`${esc(c.mobile||'—')}${n?` <a class="waChat" href="https://wa.me/${n}" target="_blank" rel="noopener noreferrer" title="Open WhatsApp chat">${whatsappIcon()} WhatsApp</a>`:''}`,`${esc(r.provider)}<br>${esc(r.policy||'—')}`,esc(r.issue),esc(r.expiry),money(r.premium||0),'Select when sharing',`<div class="rowactions">${extraButton('whatsapp','insurance',r.id,'Send WhatsApp Details','green','◉')}<button class="btn small extraAction gray" disabled title="Online tracking requires a hosted customer portal" aria-label="Copy Online Tracking Link — requires hosted portal">${icon('link')}</button>${extraButton('details','insurance',r.id,'View Full Details','blue','ⓘ')}${extraButton('copy-policy','insurance',r.id,'Copy policy details','blue','⧉')}<button class="btn small editButton" data-edit="insurance|${esc(r.id)}" title="Edit Record">${icon('edit')}</button><button class="btn small deleteButton" data-delete="insurance|${esc(r.id)}" title="Delete Record">${icon('trash')}</button></div>`]}))};
const renderBeforeActions=render;
render=function(){renderBeforeActions();if(['jobs','sales'].includes(page)){for(let row of $$('#content tbody tr')){let id=row.cells?.[0]?.textContent.trim(),r=find(page,id);if(!r)continue;let cell=row.cells[row.cells.length-1];cell.innerHTML=`<div class="rowactions">${extraButton('whatsapp',page,id,'Send WhatsApp Receipt & Bill','green','◉')}<button class="btn small editButton" data-edit="${page}|${esc(id)}" title="${page==='jobs'?'Edit Job Card':'Edit Sale'}">${icon('edit')}</button><button class="btn small printButton" data-invoice="${page}|${esc(id)}" title="View & Print Tax Invoice" aria-label="View and print invoice">${icon('print')}</button>${page==='sales'?extraButton('thermal',page,id,'Print 80mm Thermal Slip','blue','▤'):''}${extraButton('archive',page,id,page==='sales'?'Delete Sale (Restores Stock)':'Delete Job Card','red',icon('trash'))}</div>`}}if(page==='payments'){for(let row of $$('#content tbody tr')){let receiveButton=row.querySelector('[data-receive]');if(!receiveButton)continue;let [key,id]=receiveButton.dataset.receive.split('|');receiveButton.parentNode.insertAdjacentHTML('beforeend',extraButton('reminder',key,id,'Send WhatsApp Due Reminder','green','◉'))}}};
document.addEventListener('click',async e=>{let button=e.target.closest('[data-extra-action]');if(!button)return;if(['staff-jobs','salary'].includes(button.dataset.extraAction))return;e.preventDefault();e.stopImmediatePropagation();let {extraAction:a,key,id}=button.dataset,r=find(key,id);if(a==='undo'){let item=db.trash?.find(x=>x.key===key&&x.record.id===id);if(!item||find(key,id))return toast('Unable to restore: record missing or ID already exists');let snapshot=JSON.parse(JSON.stringify(db));db[key].push(item.record);db.receipts.push(...item.receipts);db.trash=db.trash.filter(x=>x!==item);audit('Restore',id);if(save('Restored')===false){db=snapshot;return}closeModal();render();return}if(!r)return;if(a==='archive')return archiveBill(key,id);if(a==='details')return showPolicy(r);if(a==='copy-policy'){try{await navigator.clipboard.writeText(policyMessage(r));toast('Policy details copied')}catch{openModal('Copy Policy Details',`<div class="formbody"><textarea rows="12" style="width:100%" aria-label="Select and copy policy details">${esc(policyMessage(r))}</textarea></div>`)}return}if(a==='thermal'){invoice(key,id);$('#modalBody').classList.add('thermalReceipt');let cleanup=()=>$('#modalBody').classList.remove('thermalReceipt');$('#closeModal').addEventListener('click',cleanup,{once:true});return}if(a==='whatsapp'||a==='reminder'){if(key==='insurance')return messagePreview(policyContact(r).mobile,policyMessage(r),{key,id});let c=find('customers',r.customer);let text=`${db.settings.name}\n${a==='reminder'?'Payment Due Reminder':'Receipt & Bill'}\nCustomer: ${c?.name||r.customerName||r.walkin||''}\nBill: ${r.id}\nDate: ${r.date}\nVehicle: ${r.vehicleNumber||number(r.bike)||''}\nTotal: ${money(billTotals(r).total)}\nPaid: ${money(paid(r))}\nBalance Due: ${money(due(r))}\nThank you.`;if(a==='whatsapp')shareSavedRecordBundleNow(key,id,c?.mobile||r.mobile,text);else messagePreview(c?.mobile||r.mobile,text,{key,id})}},true);
schemas.insurance.splice(2,0,{key:'customerName',label:'Customer Name'},{key:'mobile',label:'Mobile Number',type:'tel'},{key:'email',label:'Email'},{key:'address',label:'Address'});
/* Contact-only hydration preserves existing edited business records. */
for(let r of db.insurance){let source=window.BIKE_DOCTOR_IMPORT?.insurance?.find(x=>x.id===r.id);if(source)for(let k of ['mobile','email','address'])if(!r[k]&&source[k])r[k]=source[k]}
render();
const modalBeforeActions=openModal;
openModal=function(title,html){$('#modalBody').classList.remove('thermalReceipt');return modalBeforeActions(title,html)};
const payrollBeforeActions=payrollPage;
payrollPage=function(){let html=payrollBeforeActions();let staff=db.staff.filter(s=>s.salaryType==='Per Job').filter(matches),i=0;html=html.replace('</thead>','</thead>');html=html.replace('</tr></thead>','<th>Actions</th></tr></thead>');return html.replace(/<\/tr>/g,(match,offset)=>{if(offset<html.indexOf('<tbody'))return match;let s=staff[i++];return s?`<td><div class="rowactions">${extraButton('staff-jobs','staff',s.id,'View Assigned Jobs & Commission Breakdown','blue','ⓘ')}${extraButton('salary','staff',s.id,'Pay Due Salary via Expenses','green','₹')}</div></td></tr>`:match})};
document.addEventListener('click',e=>{let b=e.target.closest('[data-extra-action]');if(!b)return;let s=find('staff',b.dataset.id);if(!s)return;if(b.dataset.extraAction==='salary'){e.preventDefault();editRecord('expenses',null,{staff:s.id,category:'Staff Salary / Advance',description:'Salary / commission for '+s.name});return}if(b.dataset.extraAction==='staff-jobs'){e.preventDefault();let jobs=typeof payrollJobsForStaff==='function'?payrollJobsForStaff(s):db.jobs.filter(j=>j.mechanic===s.id);openModal('Assigned Jobs & Commission Breakdown',`<div class="formbody"><p>${esc(s.name)} · ${esc(s.salary)}% of completed/delivered labour.</p>${table(['Job','Status','Labour','Earned Commission'],jobs.map(j=>[esc(j.id),esc(j.status),money(billTotals(j).labour),money((typeof payrollJobIsPayable==='function'?payrollJobIsPayable(j):['Completed','Delivered'].includes(j.status))?billTotals(j).labour*Number(s.salary)/100:0)]))}</div>`)}},true);
render();

/* Imported job cards remain editable, with billing recalculated only after billing changes. */
function billingSignature(b){return JSON.stringify([b.serviceLines||[],b.partLines||[],Number(b.discount||0),Number(b.tax||0)])}
function totalsForEditedBill(b){return b.importedTotals&&b.importedBillingSignature===billingSignature(b)?{...b.importedTotals}:originalBillTotals(b)}
const totalsBeforeEditable=billTotals;
billTotals=function(b){return b.importedBillingSignature?totalsForEditedBill(b):totalsBeforeEditable(b)};
const formBeforeEditable=billForm;
billForm=function(key,id,initial){let b=id&&find(key,id);if(key!=='jobs'||!b?.imported)return formBeforeEditable(key,id,initial);let copy=structuredClone(b);copy.importedBillingSignature=copy.importedBillingSignature||billingSignature(copy);let index=db[key].indexOf(b);db[key][index]=copy;try{originalBillForm(key,id,initial)}finally{db[key][index]=b}let form=$('#billForm');if(!form)return;let advance=form.querySelector('[name="advance"]');if(advance){advance.readOnly=false;advance.title='Update the initial advance amount here.'}form.onsubmit=saveBill;updateBillTotals()};
const updateBeforeEditable=updateBillTotals;
updateBillTotals=function(){updateBeforeEditable();if(jobDraft?.record.imported){let b=jobDraft.record;$('#sumDue').textContent=money(Math.max(0,billTotals(b).total-paid(b)))}};
const saveBeforeEditable=saveBill;
saveBill=function(e){if(!jobDraft?.record.imported)return saveBeforeEditable(e);e.preventDefault();let {key,id,record}=jobDraft,data={...record,...Object.fromEntries(new FormData(e.target))};for(let k of ['discount','tax'])data[k]=Number(data[k]||0);data.advance=Number(data.advance??record.advance);if(!Number.isFinite(data.advance)||data.advance<0)return toast('Enter a valid advance or paid amount.');let total=billTotals(data).total;if(!data.customer||find('bikes',data.bike)?.customer!==data.customer)return toast('Select a vehicle belonging to this customer.');if(!data.serviceLines.length&&!data.partLines.length)return toast('Add at least one service or part.');if(data.serviceLines.some(l=>!l.service||Number(l.charge)<0)||data.partLines.some(l=>!l.part||Number(l.qty)<=0||Number(l.price)<0))return toast('Complete each service and part line with valid amounts.');if(data.discount<0||data.tax<0||data.tax>100||data.discount>originalBillTotals({...data,discount:0}).labour+originalBillTotals({...data,discount:0}).parts)return toast('Check discount and tax amounts.');if(total<paid(data))return toast('Bill total cannot be less than the recorded payments.');if(data.status==='Cancelled'&&paid(data)>0)return toast('Reverse recorded payments before cancelling this job.');let old=find(key,id),partsChanged=JSON.stringify(old.partLines)!==JSON.stringify(data.partLines),reactivated=old.status==='Cancelled'&&data.status!=='Cancelled';if((partsChanged||reactivated)&&data.status!=='Cancelled'){let used={};for(let l of data.partLines)used[l.part]=(used[l.part]||0)+Number(l.qty);for(let [part,qty]of Object.entries(used))if(qty>stock(part,id))return toast('Not enough stock for '+name('parts',part));}let before=structuredClone(db);if(data.importedBillingSignature!==billingSignature(data))delete data.importedTotals;data.customerName=name('customers',data.customer);data.vehicleNumber=number(data.bike);data.mechanicName=name('staff',data.mechanic);db[key][db[key].findIndex(x=>x.id===id)]=data;audit('Update',id+' edited');if(save('Job Card updated')===false){db=before;return}closeModal();render()};
(function installHorizontalScrolling(){
 if(typeof requestAnimationFrame!=="function"||typeof ResizeObserver!=="function")return;
 let pending=false;const known=new WeakSet();
 function enhance(){pending=false;for(let wrap of document.querySelectorAll('.tablewrap,.jobDialog #billForm>.formbody')){let table=wrap.classList.contains('formbody')?wrap.querySelector('.jobSplit'):wrap.querySelector('table');if(!table)continue;if(!known.has(wrap)){known.add(wrap);let hint=document.createElement('div'),top=document.createElement('div'),track=document.createElement('div');hint.className='tableScrollHint';hint.textContent='↔ Slide horizontally to see all columns and actions';top.className='tableScrollTop';top.tabIndex=0;top.setAttribute('role','region');top.setAttribute('aria-label','Scroll table left and right');top.appendChild(track);wrap.before(hint,top);wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Scrollable table');let syncing=false;top.addEventListener('scroll',()=>{if(syncing)return;syncing=true;wrap.scrollLeft=top.scrollLeft;syncing=false});wrap.addEventListener('scroll',()=>{if(syncing)return;syncing=true;top.scrollLeft=wrap.scrollLeft;syncing=false});let update=()=>{let wide=table.scrollWidth>wrap.clientWidth+1;hint.hidden=top.hidden=!wide;track.style.width=Math.max(table.scrollWidth,table.offsetWidth)+'px';top.scrollLeft=wrap.scrollLeft};let observer=new ResizeObserver(update);observer.observe(wrap);observer.observe(table);update()}}
 for(let calendar of document.querySelectorAll('.calendar'))if(!calendar.parentElement.classList.contains('calendarScroll')){let shell=document.createElement('div');shell.className='calendarScroll';calendar.before(shell);shell.appendChild(calendar)}
 }
 function schedule(){if(pending)return;pending=true;requestAnimationFrame(enhance)}
 new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});schedule();window.addEventListener('resize',schedule);
})();


/* Vehicle compatibility belongs to the part master, separate from its manufacturer brand. */
function partOptions(){return db.parts.map(p=>({value:p.id,label:p.name+' — '+p.id+([p.vehicleMake,p.vehicleModel].filter(Boolean).length?' — '+[p.vehicleMake,p.vehicleModel].filter(Boolean).join(' / '):'')}))}
function partVehicleMakes(){return [...new Set([...(db.lists['Vehicle Brands']||[]),...db.bikes.map(b=>b.brand),...db.parts.map(p=>p.vehicleMake)].filter(Boolean))].sort()}
function partVehicleModels(make){return [...new Set([...(typeof modelOptions!=='undefined'?modelOptions[make]||[]:[]),...db.bikes.filter(b=>b.brand===make).map(b=>b.model),...db.parts.filter(p=>p.vehicleMake===make).map(p=>p.vehicleModel)].filter(Boolean))].sort()}
schemas.parts.splice(schemas.parts.findIndex(f=>f.key==='brand')+1,0,{key:'vehicleMake',label:'Vehicle Make'},{key:'vehicleModel',label:'Vehicle Model'});
schemas.parts.splice(schemas.parts.findIndex(f=>f.key==='brand')+1,0,{key:'partType',label:'Part Type',type:'select',options:['Genuine','Aftermarket'],default:'Genuine'});
schemas.parts.splice(schemas.parts.findIndex(f=>f.key==='purchase')+1,0,{key:'purchaseDate',label:'Purchase Date',type:'date'});
const editBeforePartVehicles=editRecord;
editRecord=function(key,id,initial){editBeforePartVehicles(key,id,initial);if(key!=='parts')return;let form=$('#recordForm'),make=form?.querySelector('[name="vehicleMake"]'),model=form?.querySelector('[name="vehicleModel"]');if(!make||!model)return;let makeList=document.createElement('datalist'),modelList=document.createElement('datalist');makeList.id='partMakeOptions';modelList.id='partModelOptions';make.setAttribute('list',makeList.id);model.setAttribute('list',modelList.id);make.placeholder='Select or type a make; leave blank for universal';model.placeholder='Select or type a model';makeList.innerHTML=partVehicleMakes().map(v=>`<option value="${esc(v)}"></option>`).join('');let refresh=()=>modelList.innerHTML=partVehicleModels(make.value).map(v=>`<option value="${esc(v)}"></option>`).join('');make.addEventListener('input',()=>{model.value='';refresh()});form.append(makeList,modelList);refresh()};
const editBeforePartInteger=editRecord;
editRecord=function(key,id,initial){editBeforePartInteger(key,id,initial);if(key!=='parts')return;const form=$('#recordForm');if(!form)return;const opening=form.querySelector('[name="opening"]');if(opening){opening.step='1';opening.addEventListener('input',()=>{if(opening.value.includes('.'))opening.setCustomValidity('Opening stock must be a whole number.');else opening.setCustomValidity('')});const submit=form.onsubmit;form.onsubmit=e=>{if(!Number.isInteger(Number(opening.value))||Number(opening.value)<0){e.preventDefault();opening.setCustomValidity('Opening stock must be a whole number.');opening.reportValidity();return}return submit(e)}}};
const renderBeforePartPriceAfterGst=render;
render=function(){renderBeforePartPriceAfterGst();if(page!=='parts')return;const table=$('#content table');if(!table||table.dataset.afterGstAdded)return;const headers=[...table.querySelectorAll('thead th')],purchaseIndex=headers.findIndex(cell=>cell.textContent.trim()==='Purchase Price');if(purchaseIndex<0)return;const header=document.createElement('th');header.textContent='Purchase Price After GST';headers[purchaseIndex].after(header);for(const row of table.querySelectorAll('tbody tr')){const cells=[...row.cells];const raw=cells[purchaseIndex]?.textContent.replace(/[^0-9.-]/g,'');const purchase=Number(raw||0);const partId=cells[0]?.textContent.trim();const part=find('parts',partId);const cell=document.createElement('td');cell.textContent=money(purchase*(1+Number(part?.gst||0)/100));cells[purchaseIndex]?.after(cell)}table.dataset.afterGstAdded='true'};




